/* 最小 jQuery 替身（约 1 KB）
 * 本站对 jQuery 的唯一使用点是主题那段灯箱初始化：jQuery('[data-fancybox="gallery"]').fancybox({...})
 * 主题自带的脚本、评论、搜索、灯箱本身都是原生 JS，不依赖 jQuery。
 * 这里只实现被用到的最小 API；将来若需要完整 jQuery，把官方文件放回本路径即可。
 */
(function (w, d) {
  function J(sel) {
    if (!(this instanceof J)) return new J(sel);
    var list = [];
    if (typeof sel === 'string') list = [].slice.call(d.querySelectorAll(sel));
    else if (sel && sel.nodeType) list = [sel];
    else if (sel && typeof sel.length === 'number') list = [].slice.call(sel);
    this.length = list.length;
    for (var i = 0; i < list.length; i++) this[i] = list[i];
  }
  J.prototype.each = function (fn) { for (var i = 0; i < this.length; i++) fn.call(this[i], i, this[i]); return this; };
  J.prototype.on = function (ev, fn) { return this.each(function () { this.addEventListener(ev, fn); }); };
  J.prototype.ready = function (fn) { if (d.readyState !== 'loading') fn(); else d.addEventListener('DOMContentLoaded', fn); return this; };
  function $(sel) { return new J(sel); }
  $.fn = J.prototype;
  $.each = function (arr, fn) { for (var i = 0; i < arr.length; i++) fn(i, arr[i]); return arr; };
  w.jQuery = w.$ = $;
})(window, document);